HotelSearchResults:
query HotelSearchResults($tripStateId: ID!, $sortCriterion: SortCriterion, $filters: HotelFiltersInput, $dateFormats: DateFormats, $paging: HotelPage, $departureDateFormat: DateFormats, $timeFormat: DateFormats, $currencyFormat: CurrencyFormats) {
  hotelSearchResults(
    tripStateId: $tripStateId
    filters: $filters
    sortCriterion: $sortCriterion
    paging: $paging
  ) {
    hotelCount
    filteredHotelCount
    isNumberOfNightsAdjusted
    hotels {
      hotel {
        estabId
        name
        starRating
        numberOfPhotos
        geography {
          location
          country
          province
          latitude
          longitude
          __typename
        }
        tripadvisorFeedback {
          rating
          numberOfReviews
          ratingImageUrl
          tripAdvisorURL
          reviews {
            title
            comment
            publishedDate
            ratingImageUrl
            __typename
          }
          __typename
        }
        trustYouReviewClusterId
        __typename
      }
      skywardsMiles {
        additionalMiles
        flightMiles
        __typename
      }
      pricingSummary {
        conversionUrl
        boardTypeDescription
        price
        priceFormatted(format: $currencyFormat)
        pricePerNightFormatted(format: $currencyFormat)
        pricePerPersonFormatted(format: $currencyFormat)
        wasPrice
        wasPriceFormatted(format: $currencyFormat)
        wasPricePerPerson
        wasPricePerPersonFormatted(format: $currencyFormat)
        refundable {
          refundCutOffDate
          isRefundable
          __typename
        }
        includedExtras
        callout {
          text
          themeColor
          __typename
        }
        hypeMessages(format: $dateFormats) {
          title
          description
          descriptionHeader
          type
          __typename
        }
        checkInDate
        numberOfNights
        departureDate
        teaserPrice(rounded: true) {
          parts {
            type
            value
            __typename
          }
          value
          formatted
          __typename
        }
        teaserPricePerPerson(rounded: true) {
          parts {
            type
            value
            __typename
          }
          value
          formatted
          __typename
        }
        __typename
      }
      flight {
        flightId
        flightDetailsId
        outboundLeg {
          duration
          airlines {
            name
            code
            imageName
            __typename
          }
          duration
          departureAirport {
            airportCode
            title
            __typename
          }
          stops
          arrivalAirport {
            airportCode
            title
            __typename
          }
          departureDateTime {
            date(format: $departureDateFormat)
            time(format: $timeFormat)
            __typename
          }
          arrivalDateTime {
            date(format: $departureDateFormat)
            time(format: $timeFormat)
            __typename
          }
          totalBagsIncluded
          dayDifference
          segments {
            airline {
              name
              imageName
              __typename
            }
            departureAirport {
              airportCode
              title
              __typename
            }
            arrivalAirport {
              airportCode
              title
              __typename
            }
            flightNumber
            departureDateFormatted
            arrivalDateFormatted
            layoverTime
            dayDifference
            operatingAirline {
              name
              code
              imageName
              __typename
            }
            cabinClass
            departureDateTime {
              date(format: $departureDateFormat)
              time(format: $timeFormat)
              __typename
            }
            arrivalDateTime {
              date(format: $departureDateFormat)
              time(format: $timeFormat)
              __typename
            }
            duration
            __typename
          }
          __typename
        }
        inboundLeg {
          duration
          airlines {
            name
            code
            imageName
            __typename
          }
          duration
          departureAirport {
            airportCode
            title
            __typename
          }
          stops
          arrivalAirport {
            airportCode
            title
            __typename
          }
          departureDateTime {
            date(format: $departureDateFormat)
            time(format: $timeFormat)
            __typename
          }
          arrivalDateTime {
            date(format: $departureDateFormat)
            time(format: $timeFormat)
            __typename
          }
          totalBagsIncluded
          dayDifference
          segments {
            airline {
              name
              imageName
              __typename
            }
            departureAirport {
              airportCode
              title
              __typename
            }
            arrivalAirport {
              airportCode
              title
              __typename
            }
            flightNumber
            departureDateFormatted
            arrivalDateFormatted
            layoverTime
            dayDifference
            operatingAirline {
              name
              code
              imageName
              __typename
            }
            cabinClass
            departureDateTime {
              date(format: $departureDateFormat)
              time(format: $timeFormat)
              __typename
            }
            arrivalDateTime {
              date(format: $departureDateFormat)
              time(format: $timeFormat)
              __typename
            }
            duration
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    availableFilters {
      ... on CheckboxFilterGroup {
        id
        name
        open
        type
        items {
          id
          selected
          label
          count
          __typename
        }
        pill
        __typename
      }
      ... on RangeFilterGroup {
        id
        name
        open
        type
        max
        min
        upper
        lower
        formatString
        step
        __typename
      }
      ... on TextFilter {
        id
        name
        open
        type
        value
        __typename
      }
      __typename
    }
    sortCriterion
    hotels {
      numberOfNights
      hotel {
        customerFeedback {
          overallRating
          numberOfReviews
          overallRatingDescription
          __typename
        }
        tags {
          text
          themeColor
          __typename
        }
        __typename
      }
      pricingSummary {
        discountTypes
        cityTaxFormatted
        wasPriceFormatted(format: $currencyFormat)
        isSponsored
        impressionUrl
        clickUrl
        conversionUrl
        deposit
        depositFormatted(format: $currencyFormat)
        callout {
          text
          themeColor
          __typename
        }
        monthlyInstalment {
          isAvailable
          initialPayment
          initialPaymentFormatted(format: $currencyFormat)
          subsequentPayment
          subsequentPaymentFormatted(format: $currencyFormat)
          numberOfInstalments
          __typename
        }
        __typename
      }
      __typename
    }
    stopSellMessage {
      message
      title
      __typename
    }
    tripStateId
    __typename
  }
}

